import { MeshBasicNodeMaterial, Mesh, Group, PlaneGeometry } from 'three/webgpu';
import { texture, uv, vec2, vec4, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  const group0 = new Group();
  group.add(group0);

  // Atlas info from spec — region 0,0,512,320 of atlas 0
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasTotal = { w: 1024, h: 1024 };

  const tex = config.imageUrl ? null : null;
  // Load texture async
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
      t.colorSpace = ctx.THREE.SRGBColorSpace;
      mat.map = t;
      mat.needsUpdate = true;
    }).catch(() => {});
  }

  // Plane sized to roughly fit label: compact card-label panel
  const planeW = 2.2;
  const planeH = (atlasRect.h / atlasRect.w) * planeW;
  const geometry = new PlaneGeometry(planeW, planeH);

  // Background panel material — dark surface, maps onto atlas region
  const mat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.96 });
  mat.color = new ctx.THREE.Color(colors.surface);

  const cardMesh = new Mesh(geometry, mat);
  cardMesh.position.set(0, 0, 0);
  group0.add(cardMesh);

  // Accent edge bar (thin emissive accent strip along bottom) — Interactive focus indicator
  const accentBarGeo = new PlaneGeometry(planeW, 0.05);
  const accentMat = new MeshBasicNodeMaterial({ color: new ctx.THREE.Color(colors.accent), transparent: true, opacity: 0.0 });
  const accentBar = new Mesh(accentBarGeo, accentMat);
  accentBar.position.set(0, -planeH / 2 + 0.02, 0.001);
  group0.add(accentBar);

  // Header text — "Journal 2"
  const textColor = colors.paper;
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((it) => it.role === 'headline') || { text: 'Journal 2', typography: { fontSize: 39 } };

  const headlineMesh = ctx.fontAtlas.createText(String(headlineItem.text || 'Journal 2'), {
    fontSize: 0.34,
    color: textColor,
    align: 'center',
  });
  headlineMesh.position.set(0, 0.06, 0.002);
  group0.add(headlineMesh);

  const captionMesh = ctx.fontAtlas.createText('ENTRY 02', {
    fontSize: 0.09,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 0.08,
  });
  captionMesh.position.set(0, -0.2, 0.002);
  group0.add(captionMesh);

  // Interaction handlers
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group0.position, { y: 0.15, duration: 0.4, ease: 'power3.out' }, 0);
  hoverTl.to(group0.position, { z: 0.02, duration: 0.4, ease: 'power3.out' }, 0);
  hoverTl.to(accentMat, { opacity: 1.0, duration: 0.4, ease: 'power2.out' }, 0);
  hoverTl.to(headlineMesh.position, { y: 0.11, duration: 0.4, ease: 'power3.out' }, 0);

  let hoverActive = false;

  const handlers = {
    onPointerEnter: () => {
      if (!hoverActive) {
        hoverActive = true;
        hoverTl.play();
      }
    },
    onPointerLeave: () => {
      if (hoverActive) {
        hoverActive = false;
        hoverTl.reverse();
      }
    },
    onPointerDown: () => {
      gsap.to(group0.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
    },
    onPointerUp: () => {
      gsap.timeline()
        .to(group0.scale, { x: 1.0, y: 1.0, duration: 0.18, ease: 'power4.out' })
        .to(group0.scale, { x: 1.0, y: 1.0, duration: 0.0 });
      ctx.emit('hub-journal.select', { id: 'journal-2' });
    },
    onClick: () => {
      ctx.emit('hub-journal.select', { id: 'journal-2' });
    },
  };

  // Mark interactive and enable raycasting via userData
  group0.userData.interactive = true;
  cardMesh.userData.interactive = true;

  // Cinematic primitive: parallax-scroll
  let parallaxResult = null;
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    if (p.name === 'parallax-scroll') {
      parallaxResult = ctx.primitives['parallax-scroll'](group0, { intensity: 0.25, ...(p.params || {}) });
    }
  }

  // Entrance settle
  group0.position.set(0, -0.4, 0);
  group0.scale.setScalar(0.95);
  const introTl = gsap.timeline();
  introTl
    .to(group0.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0)
    .to(group0.position, { z: 0, duration: 0.7, ease: 'power3.out' }, 0)
    .to(group0.scale, { x: 1.04, y: 1.04, duration: 0.45, ease: 'power3.out' }, 0)
    .to(group0.scale, { x: 1.0, y: 1.0, duration: 0.45, ease: 'power4.out' }, 0.3);

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    hoverTl.kill();
    introTl.kill();
    if (parallaxResult && typeof parallaxResult.cleanup === 'function') {
      parallaxResult.cleanup();
    }
    geometry.dispose();
    accentBarGeo.dispose();
    mat.dispose();
    accentMat.dispose();
  };

  return group;
}
